// Entradas
var irrad = POA.value;       // Irradiação do dia em Wh/m²
var temp = Module1.value;     // Temperatura instantânea do módulo em °C
var KWp = Capacity.value;            // Potência pico do sistema em kW
var coef_temp = -0.0030;     // Coeficiente de temperatura (%/°C)

// Energia esperada ajustada pela temperatura
var tempFactor = 1 + ((temp - 25) * coef_temp); // Fator de correção térmica
var expectedEnergy = irrad * KWp * tempFactor;  // em Wh

return expectedEnergy/1000;  // Resultado em KWh

